package eit_acquisition_coordinator.EIT_Acquisition_Coordinator

import org.sireum._
import art._
import eit_acquisition_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait AcquisitionEvidenceQualification_Api {
  def id: Art.BridgeId
  def calibrationSample_Id : Art.PortId
  def impedanceSample_Id : Art.PortId
  def acquisitionEvidence_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var acquisitionEvidence: EIT_Acquisition_Coordinator.AcquisitionEvidence.Type = $

  def put_acquisitionEvidence(value : EIT_Acquisition_Coordinator.AcquisitionEvidence.Type) : Unit = {
    Contract(
      Modifies(acquisitionEvidence),
      Ensures(
        acquisitionEvidence == value
      )
    )
    Spec {
      acquisitionEvidence = value
    }

    Art.putValue(acquisitionEvidence_Id, EIT_Acquisition_Coordinator.AcquisitionEvidence_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class AcquisitionEvidenceQualification_Initialization_Api (
  val id: Art.BridgeId,
  val calibrationSample_Id : Art.PortId,
  val impedanceSample_Id : Art.PortId,
  val acquisitionEvidence_Id : Art.PortId) extends AcquisitionEvidenceQualification_Api

@datatype class AcquisitionEvidenceQualification_Operational_Api (
  val id: Art.BridgeId,
  val calibrationSample_Id : Art.PortId,
  val impedanceSample_Id : Art.PortId,
  val acquisitionEvidence_Id : Art.PortId) extends AcquisitionEvidenceQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var calibrationSample: EIT_Acquisition_Coordinator.CalibrationSample = $

  def get_calibrationSample() : Option[EIT_Acquisition_Coordinator.CalibrationSample] = {
    Contract(
      Ensures(
        Res == Some(calibrationSample)
      )
    )
    val value : Option[EIT_Acquisition_Coordinator.CalibrationSample] = Art.getValue(calibrationSample_Id) match {
      case Some(EIT_Acquisition_Coordinator.CalibrationSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port calibrationSample.  Expecting 'EIT_Acquisition_Coordinator.CalibrationSample_Payload' but received ${v}")
        None[EIT_Acquisition_Coordinator.CalibrationSample]()
      case _ => None[EIT_Acquisition_Coordinator.CalibrationSample]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var impedanceSample: EIT_Acquisition_Coordinator.ImpedanceSample = $

  def get_impedanceSample() : Option[EIT_Acquisition_Coordinator.ImpedanceSample] = {
    Contract(
      Ensures(
        Res == Some(impedanceSample)
      )
    )
    val value : Option[EIT_Acquisition_Coordinator.ImpedanceSample] = Art.getValue(impedanceSample_Id) match {
      case Some(EIT_Acquisition_Coordinator.ImpedanceSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port impedanceSample.  Expecting 'EIT_Acquisition_Coordinator.ImpedanceSample_Payload' but received ${v}")
        None[EIT_Acquisition_Coordinator.ImpedanceSample]()
      case _ => None[EIT_Acquisition_Coordinator.ImpedanceSample]()
    }
    return value
  }
}
